// Numbers in words, in any language Unicode CLDR has spell-out rules for.
//
// Node's Intl formats numbers but has no spell-out, so this is a small
// interpreter for ICU's rule-based number format (RBNF) over CLDR's own
// rules, vendored in ./rbnf/cldr-spellout.json (regenerated by
// scripts/gen-rbnf-spellout.ts; Unicode licence in ./rbnf/LICENSE). It reads
// the two public rule sets the speech pass uses, %spellout-numbering-year and
// %spellout-numbering, for non-negative integers only: the vendored data keeps
// no negative, fraction, infinity or NaN rules.
//
// The rule semantics follow ICU4J's NFRule/NFRuleSet/NFSubstitution: rule
// search by base value with the roll-back for an even multiple, optional
// [bracketed] text split into a base and a base+1 rule, the << / >> / ==
// substitutions (named rule set, same set, decimal pattern, and the >>>
// predecessor form), and the $(cardinal|ordinal,…)$ plural text. Anything the
// interpreter cannot follow returns null and the caller keeps the digits.
// scripts/rbnf-spellout.test.ts checks it against ICU's own output.
import { readFileSync } from 'node:fs';

type SubKind = 'multiplier' | 'modulus' | 'same';

interface Substitution {
  kind: SubKind;
  pos: number;
  // A rule set by name (null = the owning set), or a decimal pattern.
  ruleSet: string | null;
  decimal: string | null;
  // `>>>`: format the remainder with the rule before this one, no search.
  predecessor: Rule | null;
}

interface Rule {
  base: number;
  radix: number;
  exponent: number;
  text: string;
  subs: Substitution[];
  plural: { type: 'cardinal' | 'ordinal'; cases: Map<string, string> } | null;
}

interface RuleSet {
  name: string;
  rules: Rule[];
}

interface Locale {
  tag: string;
  sets: Map<string, RuleSet>;
}

const RECURSION_LIMIT = 64;
// Integers beyond this are not spoken numbers (phone numbers, ids, counters).
export const SPELLOUT_MAX = 999_999_999;

function power(radix: number, exponent: number): number {
  return radix ** exponent;
}

function expectedExponent(base: number, radix: number): number {
  if (radix === 0 || base < 1) return 0;
  const guess = Math.floor(Math.log(base) / Math.log(radix));
  return power(radix, guess + 1) <= base ? guess + 1 : guess;
}

const RULE_PREFIXES = ['<<', '<%', '<#', '<0', '>>', '>%', '>#', '>0', '=%', '=#', '=0'];

function indexOfRulePrefix(text: string): number {
  let result = -1;
  for (const p of RULE_PREFIXES) {
    const at = text.indexOf(p);
    if (at !== -1 && (result === -1 || at < result)) result = at;
  }
  return result;
}

function parsePlural(body: string): Map<string, string> {
  const cases = new Map<string, string>();
  const re = /\s*(=?[\w.]+)\s*\{([^}]*)\}/gy;
  let m: RegExpExecArray | null;
  while ((m = re.exec(body))) cases.set(m[1], m[2]);
  if (!cases.has('other')) throw new Error(`plural without other: ${body}`);
  return cases;
}

// Pulls each substitution out of the text, leaving its position (NFRule
// extractSubstitutions/extractSubstitution).
function extractSubstitutions(rule: Rule, text: string, predecessor: Rule | null): void {
  rule.text = text;
  for (let i = 0; i < 2; i++) {
    const start = indexOfRulePrefix(rule.text);
    if (start === -1) break;
    let end: number;
    if (rule.text.startsWith('>>>', start)) end = start + 2;
    else {
      const c = rule.text[start];
      end = rule.text.indexOf(c, start + 1);
      if (c === '<' && end !== -1 && end < rule.text.length - 1 && rule.text[end + 1] === c) end++;
    }
    if (end === -1) break;
    const desc = rule.text.slice(start, end + 1);
    rule.text = rule.text.slice(0, start) + rule.text.slice(end + 1);
    const c = desc[0];
    const kind: SubKind = c === '<' ? 'multiplier' : c === '>' ? 'modulus' : 'same';
    const inner = desc.slice(1, -1);
    const sub: Substitution = { kind, pos: start, ruleSet: null, decimal: null, predecessor: null };
    if (desc === '>>>') {
      if (!predecessor) throw new Error('>>> without a preceding rule');
      sub.predecessor = predecessor;
    } else if (inner.startsWith('%')) sub.ruleSet = inner;
    else if (inner.startsWith('#') || inner.startsWith('0')) sub.decimal = inner;
    else if (inner !== '') throw new Error(`unsupported substitution ${desc}`);
    else if (kind === 'same') throw new Error('== substitution needs a rule set');
    rule.subs.push(sub);
  }
  const ps = rule.text.indexOf('$(');
  const pe = ps >= 0 ? rule.text.indexOf(')$', ps) : -1;
  if (pe >= 0) {
    const comma = rule.text.indexOf(',', ps);
    const type = rule.text.slice(ps + 2, comma);
    if (type !== 'cardinal' && type !== 'ordinal') throw new Error(`plural type ${type}`);
    rule.plural = { type, cases: parsePlural(rule.text.slice(comma + 1, pe)) };
  }
}

// One rule line (`200: <%%hundreds-prefix<κόσια[ >>];`) → one or two rules
// (NFRule.makeRules).
function makeRules(line: string, predecessor: Rule | null): Rule[] {
  const colon = line.indexOf(':');
  if (colon === -1) throw new Error(`rule without a base value: ${line}`);
  const descriptor = line.slice(0, colon);
  let body = line.slice(colon + 1).replace(/;\s*$/, '').replace(/^\s+/, '');
  if (body.startsWith("'")) body = body.slice(1);
  const m = /^([\d,. ]+)(?:\/([\d,. ]+))?(>*)$/.exec(descriptor.trim());
  if (!m) throw new Error(`unsupported rule descriptor: ${descriptor}`);
  const digits = (s: string) => Number(s.replace(/[,. ]/g, ''));
  const base = digits(m[1]);
  const radix = m[2] ? digits(m[2]) : 10;
  const exponent = Math.max(0, expectedExponent(base, radix) - m[3].length);
  const rule1: Rule = { base, radix, exponent, text: '', subs: [], plural: null };

  const b1 = body.indexOf('[');
  const b2 = b1 < 0 ? -1 : body.indexOf(']');
  if (b2 < 0 || b1 > b2) {
    extractSubstitutions(rule1, body, predecessor);
    return [rule1];
  }
  // `[a|b]` (CLDR 49): `a` where the bracket text would show, `b` where it
  // would be left out (ICU 79 looks for the bar anywhere in the text).
  const orElse = body.indexOf('|');
  const out: Rule[] = [];
  if (base > 0 && base % power(radix, exponent) === 0) {
    const rule2: Rule = { base, radix, exponent, text: '', subs: [], plural: null };
    const omitted = orElse >= 0 ? body.slice(orElse + 1, b2) : '';
    extractSubstitutions(rule2, body.slice(0, b1) + omitted + body.slice(b2 + 1), predecessor);
    rule1.base = base + 1;
    out.push(rule2);
  }
  const shown = orElse >= 0 ? body.slice(b1 + 1, orElse) : body.slice(b1 + 1, b2);
  extractSubstitutions(rule1, body.slice(0, b1) + shown + body.slice(b2 + 1), predecessor);
  out.push(rule1);
  return out;
}

export function parseRules(source: string): Map<string, RuleSet> {
  const sets = new Map<string, RuleSet>();
  let current: RuleSet | null = null;
  let predecessor: Rule | null = null;
  for (const raw of source.split('\n')) {
    const line = raw.trim();
    if (!line) continue;
    const head = /^(%%?[\w-]+):$/.exec(line);
    if (head) {
      current = { name: head[1], rules: [] };
      sets.set(head[1], current);
      predecessor = null;
      continue;
    }
    if (!current) throw new Error(`rule outside a rule set: ${line}`);
    const made = makeRules(line, predecessor);
    current.rules.push(...made);
    predecessor = made[made.length - 1];
  }
  for (const set of sets.values()) {
    for (let i = 1; i < set.rules.length; i++) {
      if (set.rules[i].base < set.rules[i - 1].base) throw new Error(`${set.name}: rules out of order`);
    }
    for (const rule of set.rules) {
      for (const sub of rule.subs) {
        if (sub.ruleSet && !sets.has(sub.ruleSet)) throw new Error(`${set.name}: unknown rule set ${sub.ruleSet}`);
      }
    }
  }
  return sets;
}

function shouldRollBack(rule: Rule, n: number): boolean {
  if (!rule.subs.some((s) => s.kind === 'modulus')) return false;
  const divisor = power(rule.radix, rule.exponent);
  return n % divisor === 0 && rule.base % divisor !== 0;
}

function findRule(set: RuleSet, n: number): Rule {
  const { rules } = set;
  let lo = 0;
  let hi = rules.length;
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    const base = rules[mid].base;
    if (base === n) return rules[mid];
    if (base > n) hi = mid;
    else lo = mid + 1;
  }
  if (hi === 0) throw new Error(`${set.name} cannot format ${n}`);
  if (shouldRollBack(rules[hi - 1], n)) {
    if (hi === 1) throw new Error(`${set.name} cannot roll back for ${n}`);
    return rules[hi - 2];
  }
  return rules[hi - 1];
}

const pluralRules = new Map<string, Intl.PluralRules>();

function pluralCase(locale: string, type: 'cardinal' | 'ordinal', cases: Map<string, string>, n: number): string {
  const exact = cases.get(`=${n}`);
  if (exact !== undefined) return exact;
  const key = `${locale}|${type}`;
  let pr = pluralRules.get(key);
  if (!pr) {
    pr = new Intl.PluralRules(locale, { type });
    pluralRules.set(key, pr);
  }
  return cases.get(pr.select(n)) ?? cases.get('other')!;
}

function formatDecimal(locale: string, pattern: string, n: number): string {
  if (/^0+$/.test(pattern)) return String(n).padStart(pattern.length, '0');
  if (pattern === '#,##0') return new Intl.NumberFormat(locale, { maximumFractionDigits: 0 }).format(n);
  throw new Error(`unsupported decimal pattern ${pattern}`);
}

// A string under construction, edited by insertion like ICU's StringBuilder.
interface Buffer {
  s: string;
}

function insert(buf: Buffer, pos: number, text: string): void {
  buf.s = buf.s.slice(0, pos) + text + buf.s.slice(pos);
}

function formatWithSet(loc: Locale, set: RuleSet, n: number, buf: Buffer, pos: number, depth: number): void {
  if (depth > RECURSION_LIMIT) throw new Error('rule recursion too deep');
  doFormat(loc, set, findRule(set, n), n, buf, pos, depth + 1);
}

function doFormat(loc: Locale, set: RuleSet, rule: Rule, n: number, buf: Buffer, pos: number, depth: number): void {
  let pluralStart = rule.text.length;
  let lengthOffset = 0;
  if (!rule.plural) insert(buf, pos, rule.text);
  else {
    pluralStart = rule.text.indexOf('$(');
    const pluralEnd = rule.text.indexOf(')$', pluralStart);
    const before = buf.s.length;
    if (pluralEnd < rule.text.length - 1) insert(buf, pos, rule.text.slice(pluralEnd + 2));
    const count = Math.floor(n / power(rule.radix, rule.exponent));
    insert(buf, pos, pluralCase(loc.tag, rule.plural.type, rule.plural.cases, count));
    if (pluralStart > 0) insert(buf, pos, rule.text.slice(0, pluralStart));
    lengthOffset = rule.text.length - (buf.s.length - before);
  }
  // The later substitution first, so the earlier one's position still holds.
  for (const sub of [...rule.subs].reverse()) {
    const at = pos - (sub.pos > pluralStart ? lengthOffset : 0) + sub.pos;
    const divisor = power(rule.radix, rule.exponent);
    const value = sub.kind === 'multiplier' ? Math.floor(n / divisor)
      : sub.kind === 'modulus' ? n % divisor : n;
    if (sub.predecessor) doFormat(loc, set, sub.predecessor, value, buf, at, depth + 1);
    else if (sub.decimal) insert(buf, at, formatDecimal(loc.tag, sub.decimal, value));
    else formatWithSet(loc, sub.ruleSet ? loc.sets.get(sub.ruleSet)! : set, value, buf, at, depth);
  }
}

/** `n` in words by one rule set of a parsed rule text (the test's entry point). */
export function formatWithRules(sets: Map<string, RuleSet>, localeTag: string, setName: string, n: number): string {
  const set = sets.get(setName);
  if (!set) throw new Error(`no rule set ${setName}`);
  const buf: Buffer = { s: '' };
  formatWithSet({ tag: localeTag, sets }, set, n, buf, 0, 0);
  return buf.s;
}

let data: { cldr: string; locales: Record<string, string> } | null = null;
const parsed = new Map<string, Locale | null>();

function vendored(): Record<string, string> {
  data ??= JSON.parse(readFileSync(new URL('./rbnf/cldr-spellout.json', import.meta.url), 'utf8'));
  return data!.locales;
}

// The CLDR locale with spell-out rules for a BCP-47 tag, most specific first:
// pt-PT → pt-PT, zh-TW → zh-Hant, pt-BR → pt, sr → sr. Null when none has.
export function spelloutLocale(tag: string): string | null {
  let loc: Intl.Locale;
  try {
    loc = new Intl.Locale(tag);
  } catch {
    return null;
  }
  const max = (() => {
    try {
      return loc.maximize();
    } catch {
      return loc;
    }
  })();
  const lang = loc.language === 'nb' ? 'no' : loc.language;
  const candidates = [
    loc.script && loc.region ? `${lang}-${loc.script}-${loc.region}` : null,
    loc.region ? `${lang}-${loc.region}` : null,
    max.script ? `${lang}-${max.script}` : null,
    max.region ? `${lang}-${max.region}` : null,
    lang,
  ];
  const all = vendored();
  for (const c of candidates) if (c && Object.hasOwn(all, c)) return c;
  return null;
}

function localeData(locale: string): Locale | null {
  if (!parsed.has(locale)) {
    const source = vendored()[locale];
    let loc: Locale | null = null;
    try {
      if (source) loc = { tag: locale, sets: parseRules(source) };
    } catch {
      loc = null;
    }
    parsed.set(locale, loc);
  }
  return parsed.get(locale)!;
}

export type SpelloutKind = 'year' | 'number';

/**
 * `n` in words in a CLDR locale (from spelloutLocale), as a year or a plain
 * number, in the rule sets' own form (nominative, the numbering gender).
 * Null for a locale without rules, a value out of range or a rule this
 * interpreter cannot follow: the caller keeps the digits.
 */
export function spellOut(locale: string, n: number, kind: SpelloutKind): string | null {
  if (!Number.isSafeInteger(n) || n < 0 || n > SPELLOUT_MAX) return null;
  const loc = localeData(locale);
  if (!loc) return null;
  const set = loc.sets.get(kind === 'year' ? '%spellout-numbering-year' : '%spellout-numbering');
  if (!set) return null;
  try {
    const buf: Buffer = { s: '' };
    formatWithSet(loc, set, n, buf, 0, 0);
    return buf.s;
  } catch {
    return null;
  }
}
